You can activate debugging in your browser withF12, and selectConsolein the debugger menu.

Otherwise follow these steps:

### Code Snippets

```
<!DOCTYPE html>
<html>
<body>
<h1>My First Web Page</h1>
<script>
console.log("Hello!");
</script>
</body>
</html>

---

let price = 50;
let quantity = 3;
let total = price * quantity;
console.log("Total:", total);

---

let x = 5;
let y = "5";
console.log(x + y);  // 55 (string!)
console.log(x + Number(y));  // 10 (number)

---

console.log(myValue);
// ReferenceError: myValue is not defined

---

let x;
console.log(x.length);
// TypeError: Cannot read properties of undefined

---

let x = 10;
if (x = 5) {
console.log("This runs");
}

---

let x = 10;
if (x === 5) {
console.log("This runs only if x is 5");
}

---

<script>
let a = 5;
let b = 6;
let c = a + b;
console.log(c);
```
